        ])
        openModal({
          title: npc.name, subtitle: npc.role[0].toUpperCase() + npc.role.slice(1), icon: '✚', body, size: 'small',
          footer: el('div', { class: 'row gap end' }, [
            button('Leave', closeModal, { variant: 'ghost' }),
            button('Heal Party', () => {
              const res = healAllAtNpc(state)
