290:         const density = biome === 'forest' ? 0.16 : biome === 'swamp' ? 0.13 : biome === 'frozen' ? 0.12 : biome === 'dragon' ? 0.1 : biome === 'ruins' ? 0.08 : 0.07
291:         if (rng() > density) continue
292:         let near = false
293:         for (let dy = -1; dy <= 1 && !near; dy++) for (let dx = -1; dx <= 1; dx++) {
294:           if (occupiedTall.has(`${x + dx},${y + dy}`)) { near = true; break }
295:         }
296:         if (near) continue
297:         const list = BIOMES[biome].deco
298:         let type = pick(list, rng)
299:         if (type === 'wisp' || type === 'starflower' || type === 'lantern') type = pick(list.filter(t => t !== type), rng) || type
300:         this.addDeco(type, x, y, biome, Math.floor(rng() * 4))
301:         if (TALL[type]?.solid) {
302:           this.solidGrid[i] = 1
303:           occupiedTall.add(`${x},${y}`)
304:         }
305:       }
306:     }
307:     // Boss arenas get ceremonial pillars / monoliths.
308:     for (const b of BIOME_LIST) {
309:       const p = this.bossPoints[b.id]
310:       for (let a = 0; a < 8; a++) {
311:         const ang = (a / 8) * Math.PI * 2
312:         const x = Math.round(p.x + Math.cos(ang) * 7)
313:         const y = Math.round(p.y + Math.sin(ang) * 6)
314:         if (x < 3 || y < 3 || x >= MAP_W - 3 || y >= MAP_H - 3) continue
315:         const type = b.id === 'forest' ? 'tree' : b.id === 'volcano' ? 'obsidian' : b.id === 'frozen' ? 'iceRock' : b.id === 'celestial' ? 'obelisk' : b.id === 'dragon' ? 'spike' : b.id === 'ruins' ? 'pillar' : b.id === 'desert' ? 'crystal' : 'deadTree'
316:         this.addDeco(type, x, y, b.id, a)
317:         this.solidGrid[y * MAP_W + x] = 1
318:       }
319:     }
320:   }
