459:   spawnNpcs() {
460:     for (const b of BIOME_LIST) {
461:       const town = this.towns[b.id]
462:       for (const def of npcsForBiome(b.id)) {
463:         const x = (town.x + def.offset[0]) * TILE + 8
464:         const y = (town.y + def.offset[1]) * TILE + 14
465:         this.npcs.push({ ...def, biome: b.id, x, y, home: { x, y }, dir: 'down', kind: 'npc' })
466:       }
