514:   spawnMythics() {
515:     for (const b of BIOME_LIST) {
516:       if (!this.state.flags.bosses[b.id] || this.state.flags.mythic[b.id]) continue
517:       if (this.mythics.some(m => m.biome === b.id)) continue
518:       const p = this.mythicPoints[b.id]
519:       const monster = createMonster(b.mythic.species, b.mythic.level, { friendship: 50 })
