531:   spawnTable(biome) {
532:     const night = isNight(this.state.time.minutes)
533:     const b = BIOMES[biome]
534:     const entries = []
535:     for (const m of MONSTER_LIST) {
536:       if (m.biome !== biome || m.wild === false) continue
537:       if (m.legendary) continue
538:       let weight = RARITY[m.rarity]?.weight || 10
539:       if (m.nocturnal) {
540:         if (!night) continue
541:         weight *= 2.4
542:       } else if (night) weight *= 0.72
543:       if (m.evolutions?.length) weight *= 0.8
544:       entries.push({ monster: m, weight })
545:     }
546:     if (!entries.length) entries.push({ monster: MONSTER_LIST.find(m => m.biome === biome), weight: 1 })
547:     return entries
548:   }
549: 
550:   spawnWild(biome, opts = {}) {
551:     const biomeDef = BIOMES[biome]
552:     const entries = this.spawnTable(biome)
553:     let total = entries.reduce((s, e) => s + e.weight, 0)
554:     let roll = Math.random() * total
555:     let chosen = entries[entries.length - 1]
556:     for (const e of entries) { roll -= e.weight; if (roll <= 0) { chosen = e; break } }
557:     const species = chosen.monster
558:     const level = opts.level ?? randomInt(biomeDef.level[0], biomeDef.level[1])
559:     const pos = this.findSpawnPosition(biome, opts.near)
560:     if (!pos) return null
561:     const monster = createMonster(species.id, level)
562:     monster.hp = maxHpOf(monster)
563:     markSeen(this.state, species.id)
564:     const wild = {
565:       id: `wild_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`,
566:       kind: 'wild', biome,
567:       x: pos.x * TILE + 8, y: pos.y * TILE + 12,
568:       home: { x: pos.x * TILE + 8, y: pos.y * TILE + 12 },
569:       speciesId: species.id, monster, level,
570:       vx: 0, vy: 0, moveTimer: Math.random() * 2, dir: Math.random() < 0.5 ? 'left' : 'right',
571:       bob: Math.random() * 6,
572:       spawnedAt: performance.now(),
573:     }
574:     this.wilds.push(wild)
575:     return wild
576:   }
577: 
578:   findSpawnPosition(biome, near = null) {
579:     const b = BIOMES[biome]
580:     for (let i = 0; i < 100; i++) {
581:       let tx, ty
582:       if (near) {
583:         tx = Math.floor(near.x / TILE) + randomInt(-8, 8)
584:         ty = Math.floor(near.y / TILE) + randomInt(-6, 6)
585:       } else {
586:         tx = b.center[0] + randomInt(-24, 24)
587:         ty = b.center[1] + randomInt(-20, 20)
588:       }
589:       if (tx < 5 || ty < 5 || tx >= MAP_W - 5 || ty >= MAP_H - 5) continue
590:       const i2 = ty * MAP_W + tx
591:       if (BIOME_ORDER[this.biomeGrid[i2]] !== biome) continue
592:       if (this.solidGrid[i2]) continue
593:       if (this.nearTown(tx, ty, 9)) continue
594:       const px = tx * TILE + 8, py = ty * TILE + 12
595:       if (this.player && Math.hypot(px - this.player.x, py - this.player.y) < 100) continue
596:       if (this.wilds.some(w => Math.hypot(w.x - px, w.y - py) < 40)) continue
597:       if (this.bosses.some(w => Math.hypot(w.x - px, w.y - py) < 30)) continue
598:       return { x: tx, y: ty }
599:     }
600:     return null
601:   }
