603:   // ── runtime ───────────────────────────────────────────────────────────────
604:   placePlayerFromState() {
605:     const p = this.state.player
606:     if (p.x && p.y && this.canWalk(p.x, p.y)) {
607:       this.player.x = p.x; this.player.y = p.y
608:     } else {
609:       const t = this.towns[p.biome] || this.towns.forest
610:       this.player.x = t.x * TILE + 8
611:       this.player.y = (t.y + 3) * TILE + 10
612:     }
613:     this.player.dir = p.dir || 'down'
614:     this.currentBiome = this.biomeAtPixel(this.player.x, this.player.y)
615:     // Never drop the player directly next to a wild monster on load.
616:     this.wilds = this.wilds.filter(w => Math.hypot(w.x - this.player.x, w.y - this.player.y) > 110)
617:     this.encounterCooldown = 1.5
618:   }
619: 
620:   biomeAtPixel(x, y) {
621:     const tx = clamp(Math.floor(x / TILE), 0, MAP_W - 1)
622:     const ty = clamp(Math.floor(y / TILE), 0, MAP_H - 1)
623:     return BIOME_ORDER[this.biomeGrid[ty * MAP_W + tx]]
624:   }
625: 
626:   biomeAtTile(tx, ty) {
627:     if (tx < 0 || ty < 0 || tx >= MAP_W || ty >= MAP_H) return 'celestial'
628:     return BIOME_ORDER[this.biomeGrid[ty * MAP_W + tx]]
629:   }
630: 
631:   canWalk(x, y) {
632:     const hw = 5, hh = 4
633:     for (const [ox, oy] of [[-hw, -hh], [hw, -hh], [-hw, hh], [hw, hh]]) {
634:       if (this.isSolidTile(Math.floor((x + ox) / TILE), Math.floor((y + oy) / TILE))) return false
635:     }
636:     return true
637:   }
638: 
639:   movePlayer(dx, dy) {
640:     const p = this.player
641:     if (dx) {
642:       if (this.canWalk(p.x + dx, p.y)) p.x += dx
643:       else {
644:         // slide along blocked edges
645:         const step = Math.sign(dx) * 0.5
646:         for (let i = 0; i < Math.abs(dx) * 2; i++) { if (this.canWalk(p.x + step, p.y)) p.x += step; else break }
647:       }
648:     }
649:     if (dy) {
650:       if (this.canWalk(p.x, p.y + dy)) p.y += dy
651:       else {
652:         const step = Math.sign(dy) * 0.5
653:         for (let i = 0; i < Math.abs(dy) * 2; i++) { if (this.canWalk(p.x, p.y + step)) p.y += step; else break }
654:       }
655:     }
656:     if (dx || dy) {
657:       p.dir = Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up')
658:       const moved = Math.hypot(dx, dy)
659:       this.onPlayerMoved(moved)
660:     }
661:   }
662: 
663:   onPlayerMoved(distance) {
664:     const st = this.state
665:     st.stats.steps += distance / TILE
666:     st.player.steps += distance / TILE
667:     this.stepAccumulator += distance / TILE
668:     if (this.stepAccumulator >= 1) {
669:       const steps = Math.floor(this.stepAccumulator)
670:       this.stepAccumulator -= steps
671:       this.advanceEggs(steps * 2)
672:     }
673:     const biome = this.biomeAtPixel(this.player.x, this.player.y)
674:     if (biome !== this.currentBiome) {
675:       this.currentBiome = biome
676:       st.player.biome = biome
677:       const first = !st.flags.visited[biome]
678:       visitBiome(st, biome)
679:       emit('toast', {
680:         title: first ? 'New Region Discovered' : BIOMES[biome].name,
681:         text: first ? BIOMES[biome].short + ' added to your map.' : '',
682:         icon: BIOMES[biome].icon,
683:         tone: 'region',
684:       })
685:       emit('biome-change', { biome })
686:     }
687:   }
688: 
689:   advanceEggs(steps) {
690:     for (const m of [...this.state.party, ...this.state.storage]) {
691:       if (!m.isEgg) continue
692:       m.hatchSteps = Math.max(0, m.hatchSteps - steps)
693:       if (m.hatchSteps <= 0 && !m.hatching) {
694:         m.hatching = true
695:         emit('egg-ready', { egg: m })
696:       }
697:     }
698:   }
699: 
700:   update(dt) {
701:     this.time += dt
702:     // advance game clock: one in-game minute per 1.5 real seconds
703:     this.clockAccumulator = (this.clockAccumulator || 0) + dt
704:     if (this.clockAccumulator > 1.5) {
705:       const mins = Math.floor(this.clockAccumulator / 1.5)
706:       this.clockAccumulator -= mins * 1.5
707:       advanceTime(this.state, mins * 0.9)
708:     }
709:     this.encounterCooldown = Math.max(0, this.encounterCooldown - dt)
710: 
711:     this.updateWilds(dt)
712:     this.updateSpawns(dt)
713:     this.updateResources()
714: 
715:     const near = this.nearestInteraction()
716:     const auto = this.closestWild(18)
717:     if (auto && this.encounterCooldown <= 0) {
718:       this.encounterCooldown = 1.5
719:       return { encounter: auto, near }
720:     }
721:     return { near }
722:   }
723: 
724:   updateWilds(dt) {
725:     const now = performance.now()
726:     for (const w of this.wilds) {
727:       w.bob += dt
728:       w.moveTimer -= dt
729:       if (w.moveTimer <= 0) {
730:         w.moveTimer = 1 + Math.random() * 2.6
731:         const ang = Math.random() * Math.PI * 2
732:         w.vx = Math.cos(ang) * (Math.random() < 0.35 ? 18 : 9)
733:         w.vy = Math.sin(ang) * (Math.random() < 0.35 ? 14 : 7)
734:         if (Math.abs(w.vx) > Math.abs(w.vy)) w.dir = w.vx > 0 ? 'right' : 'left'
735:       }
736:       // drift home if too far
737:       const dhome = Math.hypot(w.x - w.home.x, w.y - w.home.y)
738:       if (dhome > 90) {
739:         w.vx += (w.home.x - w.x) * 0.3 * dt
740:         w.vy += (w.home.y - w.y) * 0.3 * dt
