124:       this.towns[b.id] = { x: tx, y: ty, name: b.town.name }
125:       this.carveCircle(tx, ty, 9, T.PLAZA)
126:       const bx = clamp(b.center[0] + b.boss.offset[0], 6, MAP_W - 7)
127:       const by = clamp(b.center[1] + b.boss.offset[1], 6, MAP_H - 7)
128:       this.bossPoints[b.id] = { x: bx, y: by }
129:       this.carveCircle(bx, by, 7, T.PLAZA)
130:       const mx = clamp(b.center[0] + b.mythic.offset[0], 6, MAP_W - 7)
131:       const my = clamp(b.center[1] + b.mythic.offset[1], 6, MAP_H - 7)
132:       this.mythicPoints[b.id] = { x: mx, y: my }
