218:     if (x < 1 || y < 1 || x >= MAP_W - 1 || y >= MAP_H - 1) return
219:     const i = y * MAP_W + x
220:     this.terrainGrid[i] = terrain
221:     if (solid === true) this.solidGrid[i] = 1
222:     else if (solid === false) this.solidGrid[i] = 0
223:     else this.solidGrid[i] = (terrain === T.WATER || terrain === T.LAVA || terrain === T.OCEAN) ? 1 : 0
224:   }
225: 
226:   nearTown(x, y, r) {
227:     return Object.values(this.towns).some(t => Math.hypot(t.x - x, t.y - y) < r)
228:   }
229:   nearBoss(x, y, r) {
230:     return Object.values(this.bossPoints).some(t => Math.hypot(t.x - x, t.y - y) < r)
231:   }
232:   nearPath(x, y, r) {
233:     for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
234:       const tx = x + dx, ty = y + dy
235:       if (tx < 0 || ty < 0 || tx >= MAP_W || ty >= MAP_H) continue
236:       if (this.terrainGrid[ty * MAP_W + tx] === T.PATH) return true
237:     }
238:     return false
239:   }
240: 
241:   placeBuildings() {
242:     for (const b of BIOME_LIST) {
243:       const town = this.towns[b.id]
244:       const spots = [[-6, -5, 0], [5, -5, 1], [-7, 4, 2], [6, 5, 3]]
245:       for (const [dx, dy, variant] of spots) {
246:         const x = town.x + dx, y = town.y + dy
247:         if (x < 4 || y < 4 || x >= MAP_W - 5 || y >= MAP_H - 6) continue
248:         this.addDeco('house', x, y, b.id, variant, true, 3)
249:         for (let yy = y; yy < y + 2; yy++) for (let xx = x - 1; xx <= x + 1; xx++) this.solidGrid[yy * MAP_W + xx] = 1
250:         this.setTerrain(x, y, T.PLAZA, false)
251:       }
252:       // Town lanterns / signposts
253:       this.addDeco(b.id === 'celestial' ? 'lantern' : 'banner', town.x, town.y - 3, b.id, 0, true, 1)
254:       for (const [dx, dy] of [[-2, -6], [2, -6], [-9, 0], [8, 0]]) {
255:         const x = town.x + dx, y = town.y + dy
256:         if (!this.isSolidTile(x, y)) this.addDeco('lantern', x, y, b.id, 1, true, 1)
257:       }
258:     }
259:   }
260: 
261:   addDeco(type, x, y, biome, variant = 0, force = false, solidWidth = 1) {
262:     const info = TALL[type]
263:     if (!info) return
264:     this.decos.push({ type, x, y, biome, variant, h: info.h, solidWidth })
265:     if (info.solid || force) {
266:       for (let dy = 0; dy < 2; dy++) {
267:         for (let dx = -Math.floor(solidWidth / 2); dx <= Math.floor(solidWidth / 2); dx++) {
268:           const tx = x + dx, ty = y + dy
269:           if (tx < 0 || ty < 0 || tx >= MAP_W || ty >= MAP_H) continue
270:           this.solidGrid[ty * MAP_W + tx] = 1
271:         }
272:       }
273:     }
274:     const chunkKey = `${Math.floor(x / 12)},${Math.floor(y / 12)}`
275:     if (!this.decoChunks.has(chunkKey)) this.decoChunks.set(chunkKey, [])
276:     this.decoChunks.get(chunkKey).push(this.decos[this.decos.length - 1])
277:   }
278: 
279:   addDecorations() {
280:     const rng = mulberry32(77123)
281:     const occupiedTall = new Set()
282:     for (let y = 7; y < MAP_H - 7; y++) {
283:       for (let x = 7; x < MAP_W - 7; x++) {
284:         const i = y * MAP_W + x
285:         if (this.solidGrid[i]) continue
286:         const terrain = this.terrainGrid[i]
287:         if (terrain !== T.GROUND && terrain !== T.ASH && terrain !== T.ICE) continue
288:         if (this.nearTown(x, y, 10) || this.nearBoss(x, y, 8)) continue
289:         if (this.nearPath(x, y, 1)) continue
290:         const biome = BIOME_ORDER[this.biomeGrid[i]]
291:         const density = biome === 'forest' ? 0.16 : biome === 'swamp' ? 0.13 : biome === 'frozen' ? 0.12 : biome === 'dragon' ? 0.1 : biome === 'ruins' ? 0.08 : 0.07
292:         if (rng() > density) continue
293:         let near = false
294:         for (let dy = -1; dy <= 1 && !near; dy++) for (let dx = -1; dx <= 1; dx++) {
295:           if (occupiedTall.has(`${x + dx},${y + dy}`)) { near = true; break }
296:         }
297:         if (near) continue
298:         const list = BIOMES[biome].deco
299:         let type = pick(list, rng)
300:         if (type === 'wisp' || type === 'starflower' || type === 'lantern') type = pick(list.filter(t => t !== type), rng) || type
301:         this.addDeco(type, x, y, biome, Math.floor(rng() * 4))
302:         if (TALL[type]?.solid) {
303:           this.solidGrid[i] = 1
304:           occupiedTall.add(`${x},${y}`)
305:         }
306:       }
307:     }
308:     // Boss arenas get ceremonial pillars / monoliths.
309:     for (const b of BIOME_LIST) {
310:       const p = this.bossPoints[b.id]
311:       for (let a = 0; a < 8; a++) {
312:         const ang = (a / 8) * Math.PI * 2
313:         const x = Math.round(p.x + Math.cos(ang) * 7)
314:         const y = Math.round(p.y + Math.sin(ang) * 6)
315:         if (x < 3 || y < 3 || x >= MAP_W - 3 || y >= MAP_H - 3) continue
316:         const type = b.id === 'forest' ? 'tree' : b.id === 'volcano' ? 'obsidian' : b.id === 'frozen' ? 'iceRock' : b.id === 'celestial' ? 'obelisk' : b.id === 'dragon' ? 'spike' : b.id === 'ruins' ? 'pillar' : b.id === 'desert' ? 'crystal' : 'deadTree'
317:         this.addDeco(type, x, y, b.id, a)
318:         this.solidGrid[y * MAP_W + x] = 1
319:       }
320:     }
321:   }
322: 
323:   isSolidTile(x, y) {
324:     if (x < 0 || y < 0 || x >= MAP_W || y >= MAP_H) return true
325:     return !!this.solidGrid[y * MAP_W + x]
326:   }
