328:   // ── baked ground ──────────────────────────────────────────────────────────
329:   bakeGround() {
330:     const canvas = document.createElement('canvas')
331:     canvas.width = WORLD_W; canvas.height = WORLD_H
332:     const c = canvas.getContext('2d')
333:     c.imageSmoothingEnabled = false
334:     const pal = Object.fromEntries(BIOME_LIST.map(b => [b.id, b.palette]))
335:     for (let y = 0; y < MAP_H; y++) {
336:       for (let x = 0; x < MAP_W; x++) {
337:         const i = y * MAP_W + x
338:         const biome = BIOME_ORDER[this.biomeGrid[i]]
339:         const terrain = this.terrainGrid[i]
340:         const p = pal[biome] || pal.forest
341:         const px = x * TILE, py = y * TILE
342:         const v = this.variantGrid[i] + Math.floor(hash2(x, y, 3) * 4)
343:         let color
344:         if (terrain === T.OCEAN || terrain === T.WATER) {
345:           color = terrain === T.OCEAN ? '#204868' : p.water
346:           if (biome === 'frozen' && terrain === T.WATER) color = '#a9ddec'
347:         } else if (terrain === T.LAVA) {
348:           color = (v % 2) ? '#d6512c' : '#ef6a2e'
349:         } else if (terrain === T.ICE) {
350:           color = v % 2 ? '#a9d9e8' : '#c2e9f2'
351:         } else if (terrain === T.BRIDGE) {
352:           color = biome === 'celestial' ? '#cbbf98' : '#8a6a48'
353:         } else if (terrain === T.PATH) {
354:           color = v % 3 === 0 ? p.path2 : p.path
355:         } else if (terrain === T.PLAZA) {
356:           color = biome === 'celestial' ? '#ddd5b6' : (v % 2 ? '#b8a47e' : '#c4b18a')
357:         } else if (terrain === T.ASH) {
358:           color = v % 2 ? '#3b3130' : '#453938'
359:         } else {
360:           color = [p.ground, p.ground2, p.ground3, p.ground][v % 4]
361:         }
362:         c.fillStyle = color
363:         c.fillRect(px, py, TILE, TILE)
364: 
365:         // organic tile texture
366:         const seed = hash2(x, y, 57)
367:         if (terrain === T.GROUND) {
368:           if (seed < 0.35) {
369:             c.fillStyle = p.ground2
370:             c.fillRect(px + 3 + Math.floor(seed * 30) % 8, py + 4 + Math.floor(seed * 17) % 7, 3, 2)
371:           }
372:           if (seed > 0.9) {
373:             c.fillStyle = p.ground3
374:             c.fillRect(px + 7, py + 9, 4, 2)
375:           }
376:           if (biome === 'forest' && seed > 0.75) {
377:             c.fillStyle = '#7fcf6f'
378:             c.fillRect(px + 4, py + 11, 1, 2); c.fillStyle = '#a8e88c'; c.fillRect(px + 4, py + 10, 1, 1)
379:           }
380:           if (biome === 'desert' && seed > 0.6) {
381:             c.fillStyle = 'rgba(255,240,190,0.35)'; c.fillRect(px + 2, py + 6, 6, 1)
382:           }
383:           if (biome === 'celestial' && seed > 0.62) {
384:             c.fillStyle = 'rgba(255,248,190,0.5)'; c.fillRect(px + 5, py + 7, 2, 2)
385:           }
386:         }
387:         if ((terrain === T.OCEAN || terrain === T.WATER) && seed > 0.55) {
388:           c.fillStyle = terrain === T.OCEAN ? '#3b6c8c' : 'rgba(220,250,255,0.5)'
389:           const wx = px + 2 + Math.floor(seed * 9)
390:           c.fillRect(wx, py + 4 + Math.floor(seed * 10 % 6), 5, 1)
391:           c.fillRect(wx + 2, py + 9 + Math.floor(seed * 13 % 4), 4, 1)
392:         }
393:         if (terrain === T.LAVA) {
394:           c.fillStyle = '#ffcf6a'
395:           c.fillRect(px + 4, py + 6 + Math.floor(seed * 6), 5, 2)
396:           if (seed > 0.6) c.fillRect(px + 9, py + 2, 2, 3)
397:         }
398:         if (terrain === T.BRIDGE) {
399:           c.fillStyle = 'rgba(45,25,15,0.55)'
400:           for (let k = 0; k < 4; k++) c.fillRect(px, py + k * 4, TILE, 1)
401:           c.fillStyle = '#3f2a1c'
402:           c.fillRect(px, py, 1, TILE); c.fillRect(px + TILE - 1, py, 1, TILE)
403:         }
404:         if (terrain === T.PATH || terrain === T.PLAZA) {
405:           if (seed > 0.6) { c.fillStyle = 'rgba(80,60,40,0.35)'; c.fillRect(px + 3, py + 5, 2, 2); c.fillRect(px + 10, py + 11, 2, 1) }
406:           if (seed < 0.12) { c.fillStyle = 'rgba(255,245,210,0.35)'; c.fillRect(px + 8, py + 7, 1, 1) }
407:         }
408:         // shoreline edges
409:         if (terrain !== T.WATER && terrain !== T.OCEAN && terrain !== T.LAVA) {
410:           const above = this.terrainGrid[(y - 1) * MAP_W + x]
411:           if (above === T.WATER || above === T.OCEAN) { c.fillStyle = 'rgba(240,250,255,0.6)'; c.fillRect(px, py, TILE, 2) }
412:         }
413:       }
414:     }
415:     // Fine details on plaza: mosaic around town centre
416:     for (const t of Object.values(this.towns)) {
417:       const cx = t.x * TILE + 8, cy = t.y * TILE + 8
418:       c.strokeStyle = 'rgba(255,240,200,0.28)'
419:       c.lineWidth = 1
420:       c.beginPath(); c.arc(cx, cy, 5 * TILE, 0, Math.PI * 2); c.stroke()
421:       c.beginPath(); c.arc(cx, cy, 2.4 * TILE, 0, Math.PI * 2); c.stroke()
422:     }
423:     this.mapCanvas = canvas
424:   }
