426:   buildMinimap() {
427:     const canvas = document.createElement('canvas')
428:     canvas.width = MAP_W; canvas.height = MAP_H
429:     const c = canvas.getContext('2d')
430:     for (let y = 0; y < MAP_H; y++) {
431:       for (let x = 0; x < MAP_W; x++) {
432:         const i = y * MAP_W + x
433:         const terrain = this.terrainGrid[i]
434:         const b = BIOMES[BIOME_ORDER[this.biomeGrid[i]]] || BIOMES.forest
435:         let col = b.palette.ground
436:         if (terrain === T.OCEAN) col = '#1b3f5c'
437:         else if (terrain === T.WATER) col = '#356b8a'
438:         else if (terrain === T.LAVA) col = '#e2572c'
439:         else if (terrain === T.PATH) col = '#c9b48b'
