471:   spawnResources() {
472:     const rng = mulberry32(9981)
473:     for (const b of BIOME_LIST) {
474:       let placed = 0, attempts = 0
475:       while (placed < 9 && attempts++ < 200) {
476:         const x = b.center[0] + Math.round((rng() - 0.5) * 38)
477:         const y = b.center[1] + Math.round((rng() - 0.5) * 32)
478:         if (x < 6 || y < 6 || x >= MAP_W - 6 || y >= MAP_H - 6) continue
479:         if (BIOME_ORDER[this.biomeGrid[y * MAP_W + x]] !== b.id) continue
480:         if (this.isSolidTile(x, y) || this.isSolidTile(x + 1, y)) continue
481:         if (this.nearTown(x, y, 11) || this.nearBoss(x, y, 9)) continue
482:         if (this.resources.some(r => Math.hypot(r.tx - x, r.ty - y) < 4)) continue
483:         const item = pick(b.resources, rng)
484:         this.resources.push({
485:           id: `res_${b.id}_${placed}`,
486:           item,
487:           biome: b.id,
488:           tx: x, ty: y,
489:           x: x * TILE + 8, y: y * TILE + 12,
490:           available: true,
491:           respawnAt: 0,
492:           kind: 'resource',
493:         })
494:         placed++
495:       }
496:     }
