531: 
532:   spawnTable(biome) {
533:     const night = isNight(this.state.time.minutes)
534:     const b = BIOMES[biome]
535:     const entries = []
536:     for (const m of MONSTER_LIST) {
537:       if (m.biome !== biome || m.wild === false) continue
538:       if (m.legendary) continue
539:       let weight = RARITY[m.rarity]?.weight || 10
540:       if (m.nocturnal) {
541:         if (!night) continue
542:         weight *= 2.4
543:       } else if (night) weight *= 0.72
544:       if (m.evolutions?.length) weight *= 0.8
545:       entries.push({ monster: m, weight })
546:     }
547:     if (!entries.length) entries.push({ monster: MONSTER_LIST.find(m => m.biome === biome), weight: 1 })
548:     return entries
549:   }
