551:   spawnWild(biome, opts = {}) {
552:     const biomeDef = BIOMES[biome]
553:     const entries = this.spawnTable(biome)
554:     let total = entries.reduce((s, e) => s + e.weight, 0)
555:     let roll = Math.random() * total
556:     let chosen = entries[entries.length - 1]
557:     for (const e of entries) { roll -= e.weight; if (roll <= 0) { chosen = e; break } }
558:     const species = chosen.monster
559:     const level = opts.level ?? randomInt(biomeDef.level[0], biomeDef.level[1])
560:     const pos = this.findSpawnPosition(biome, opts.near)
561:     if (!pos) return null
562:     const monster = createMonster(species.id, level)
563:     monster.hp = maxHpOf(monster)
564:     markSeen(this.state, species.id)
565:     const wild = {
566:       id: `wild_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 6)}`,
567:       kind: 'wild', biome,
568:       x: pos.x * TILE + 8, y: pos.y * TILE + 12,
569:       home: { x: pos.x * TILE + 8, y: pos.y * TILE + 12 },
570:       speciesId: species.id, monster, level,
571:       vx: 0, vy: 0, moveTimer: Math.random() * 2, dir: Math.random() < 0.5 ? 'left' : 'right',
572:       bob: Math.random() * 6,
573:       spawnedAt: performance.now(),
574:     }
575:     this.wilds.push(wild)
576:     return wild
577:   }
578: 
579:   findSpawnPosition(biome, near = null) {
580:     const b = BIOMES[biome]
581:     for (let i = 0; i < 100; i++) {
582:       let tx, ty
583:       if (near) {
584:         tx = Math.floor(near.x / TILE) + randomInt(-8, 8)
585:         ty = Math.floor(near.y / TILE) + randomInt(-6, 6)
586:       } else {
587:         tx = b.center[0] + randomInt(-24, 24)
588:         ty = b.center[1] + randomInt(-20, 20)
589:       }
590:       if (tx < 5 || ty < 5 || tx >= MAP_W - 5 || ty >= MAP_H - 5) continue
591:       const i2 = ty * MAP_W + tx
592:       if (BIOME_ORDER[this.biomeGrid[i2]] !== biome) continue
593:       if (this.solidGrid[i2]) continue
594:       if (this.nearTown(tx, ty, 9)) continue
595:       const px = tx * TILE + 8, py = ty * TILE + 12
596:       if (this.player && Math.hypot(px - this.player.x, py - this.player.y) < 100) continue
597:       if (this.wilds.some(w => Math.hypot(w.x - px, w.y - py) < 40)) continue
598:       if (this.bosses.some(w => Math.hypot(w.x - px, w.y - py) < 30)) continue
599:       return { x: tx, y: ty }
600:     }
601:     return null
602:   }
