604:   // ── runtime ───────────────────────────────────────────────────────────────
605:   placePlayerFromState() {
606:     const p = this.state.player
607:     if (p.x && p.y && this.canWalk(p.x, p.y)) {
608:       this.player.x = p.x; this.player.y = p.y
609:     } else {
610:       const t = this.towns[p.biome] || this.towns.forest
611:       this.player.x = t.x * TILE + 8
612:       this.player.y = (t.y + 3) * TILE + 10
613:     }
614:     this.player.dir = p.dir || 'down'
615:     this.currentBiome = this.biomeAtPixel(this.player.x, this.player.y)
616:     // Never drop the player directly next to a wild monster on load.
617:     this.wilds = this.wilds.filter(w => Math.hypot(w.x - this.player.x, w.y - this.player.y) > 110)
618:     this.encounterCooldown = 1.5
619:   }
