621:   biomeAtPixel(x, y) {
622:     const tx = clamp(Math.floor(x / TILE), 0, MAP_W - 1)
623:     const ty = clamp(Math.floor(y / TILE), 0, MAP_H - 1)
624:     return BIOME_ORDER[this.biomeGrid[ty * MAP_W + tx]]
625:   }
626: 
627:   biomeAtTile(tx, ty) {
628:     if (tx < 0 || ty < 0 || tx >= MAP_W || ty >= MAP_H) return 'celestial'
629:     return BIOME_ORDER[this.biomeGrid[ty * MAP_W + tx]]
630:   }
631: 
632:   canWalk(x, y) {
633:     const hw = 5, hh = 4
634:     for (const [ox, oy] of [[-hw, -hh], [hw, -hh], [-hw, hh], [hw, hh]]) {
635:       if (this.isSolidTile(Math.floor((x + ox) / TILE), Math.floor((y + oy) / TILE))) return false
636:     }
637:     return true
638:   }
639: 
640:   movePlayer(dx, dy) {
641:     const p = this.player
642:     if (dx) {
643:       if (this.canWalk(p.x + dx, p.y)) p.x += dx
644:       else {
645:         // slide along blocked edges
646:         const step = Math.sign(dx) * 0.5
647:         for (let i = 0; i < Math.abs(dx) * 2; i++) { if (this.canWalk(p.x + step, p.y)) p.x += step; else break }
648:       }
649:     }
650:     if (dy) {
651:       if (this.canWalk(p.x, p.y + dy)) p.y += dy
