35:       if (monster.hp >= maxHpOf(monster) && !item.cure) return { ok: false, message: 'HP is already full.' }
36:       removeItem(state, itemId, 1)
37:       const max = maxHpOf(monster)
38:       monster.hp = item.heal === 'full' ? max : Math.min(max, monster.hp + item.heal)
39:       if (item.cure) monster.status = null
40:       return { ok: true, message: `${monster.nickname} recovered.` }
41:     }
42:     case 'cure': {
43:       if (!monster.status) return { ok: false, message: 'Nothing to cure.' }
44:       if (item.cure && !item.cure.includes(monster.status)) return { ok: false, message: 'That item does not cure this condition.' }
45:       removeItem(state, itemId, 1)
46:       monster.status = null
47:       return { ok: true, message: `${monster.nickname} is cured.` }
48:     }
49:     case 'revive': {
50:       if (monster.hp > 0) return { ok: false, message: 'That monster has not fainted.' }
51:       removeItem(state, itemId, 1)
52:       monster.hp = Math.max(1, Math.floor(maxHpOf(monster) * item.revive))
53:       return { ok: true, message: `${monster.nickname} was revived.` }
54:     }
55:     case 'gift': {
56:       removeItem(state, itemId, 1)
57:       if (item.friendship) {
58:         addFriendship(monster, item.friendship)
59:         return { ok: true, message: `${monster.nickname}'s friendship rose to ${monster.friendship}.` }
60:       }
61:       if (item.xp) {
62:         const res = gainXp(monster, item.xp)
63:         return { ok: true, message: `${monster.nickname} gained ${item.xp} EXP.`, ...res }
64:       }
65:       return { ok: true, message: 'Used.' }
66:     }
67:     default:
68:       return { ok: false, message: 'That item cannot be used here.' }
69:   }
70: }
