72: export function craftItem(state, recipeId) {
73:   const recipe = RECIPES.find(r => r.id === recipeId)
74:   if (!recipe) return { ok: false, message: 'Unknown recipe.' }
75:   for (const c of recipe.cost) {
76:     if (itemCount(state, c.item) < c.count) return { ok: false, message: `Need ${c.count}× ${getItem(c.item).name}.` }
77:   }
78:   for (const c of recipe.cost) removeItem(state, c.item, c.count)
79:   addItem(state, recipe.out.item, recipe.out.count)
80:   state.stats.crafts = (state.stats.crafts || 0) + 1
81:   return { ok: true, message: `Crafted ${recipe.out.count}× ${getItem(recipe.out.item).name}.` }
82: }
83: 
84: export function canCraft(state, recipe) {
85:   return recipe.cost.every(c => itemCount(state, c.item) >= c.count)
86: }
87: 
88: export function buyItem(state, itemId, count = 1, priceOverride = null) {
89:   const item = getItem(itemId)
90:   const price = priceOverride ?? item.price ?? 100
91:   const total = price * count
92:   if (state.player.money < total) return { ok: false, message: 'Not enough gold.' }
93:   addMoney(state, -total)
94:   addItem(state, itemId, count)
95:   return { ok: true, message: `Bought ${count}× ${item.name}.` }
96: }
97: 
98: export function sellItem(state, itemId, count = 1) {
99:   const item = getItem(itemId)
100:   if (item.type === 'key') return { ok: false, message: 'That is a key item.' }
101:   if (!removeItem(state, itemId, count)) return { ok: false, message: 'You do not have that.' }
102:   const value = Math.max(1, Math.floor((item.price || 10) * 0.5)) * count
103:   addMoney(state, value)
104:   return { ok: true, message: `Sold ${count}× ${item.name} for ${value}g.` }
105: }
106: 
107: export function healAllAtNpc(state) {
108:   for (const m of state.party) {
109:     if (m.isEgg) continue
110:     m.hp = maxHpOf(m); m.status = null; m.statusTurns = 0
111:   }
112:   for (const m of state.storage) {
113:     if (m.isEgg) continue
114:     m.hp = maxHpOf(m); m.status = null
115:   }
116:   return { ok: true, message: 'Your whole team is fully healed.' }
117: }
