267:       - name: Fetch AgentsWeb tunnel client outside the project
268:         if: env.TEST_REQUEST != 'true' && env.AGENTSWEB_SSH_ENABLED == 'true'
269:         timeout-minutes: 2
270:         shell: bash
271:         run: |
272:           set -euo pipefail
273:           /usr/bin/time -p git clone --depth=1 --filter=blob:none --sparse \
274:             https://github.com/denaidark/agent-workspace.git "$AGENTSWEB_DIR"
275:           /usr/bin/time -p git -C "$AGENTSWEB_DIR" sparse-checkout set lolgames_tunnel
276:           /usr/bin/time -p test -f "$AGENTSWEB_DIR/lolgames_tunnel/client.py"
277:       - name: Start AgentsWeb SSH session
278:         id: agentsweb
279:         timeout-minutes: 5
280:         if: env.TEST_REQUEST != 'true' && env.AGENTSWEB_SSH_ENABLED == 'true'
281:         continue-on-error: true
282:         shell: bash
283:         run: |
284:           set -euo pipefail
285:           # GITHUB_RUN_NUMBER starts at 1 in every repository, so using it here
286:           # makes every new repository's first OMG run contend for port 32001.
287:           # GITHUB_RUN_ID is globally unique and distributes runs across the
288:           # broker's 32000-32999 public-port range.
289:           REQUESTED_SSH_PORT=$((32000 + GITHUB_RUN_ID % 1000))
290:           # Reuse the runner's sshd without touching apt or preview dependencies.
291:           if [[ "$RUNNER_OS" == 'Linux' && ! -x /usr/sbin/sshd ]]; then
292:             /usr/bin/time -p timeout --kill-after=10s 90s sudo -n apt-get \
293:               -o Acquire::ForceIPv4=true -o Acquire::Retries=1 \
294:               -o Acquire::http::Timeout=20 -o Acquire::https::Timeout=20 update
295:             /usr/bin/time -p timeout --kill-after=10s 90s sudo -n apt-get \
296:               -o Acquire::ForceIPv4=true -o Acquire::Retries=1 \
297:               -o Acquire::http::Timeout=20 -o Acquire::https::Timeout=20 install -y openssh-server
298:           fi
299:           /usr/bin/time -p test -x /usr/sbin/sshd
300:           install -d -m 700 "$SSH_DIR"
301:           SSH_KEY="$RUNNER_TEMP/opencode-agentsweb-id_ed25519"
302:           SSH_PUBLIC_KEY="$SSH_KEY.pub"
303:           printf 'SSH_KEY=%s\nSSH_PUBLIC_KEY=%s\n' "$SSH_KEY" "$SSH_PUBLIC_KEY" >> "$GITHUB_ENV"
304:           ssh-keygen -t ed25519 -f "$SSH_KEY" -N '' -q
305:           chmod 600 "$SSH_KEY"
306:           install -d -m 700 "$HOME/.ssh"
307:           {
308:             cat "$SSH_PUBLIC_KEY"
309:             printf '%s\n' "$AGENTSWEB_SSH_PUBLIC_KEY"
310:           } > "$HOME/.ssh/authorized_keys"
311:           chmod 600 "$HOME/.ssh/authorized_keys"
312:           [[ "$RUNNER_OS" != 'Linux' ]] || sudo mkdir -p /run/sshd
313:           # shellcheck disable=SC2024
314:           sudo /usr/sbin/sshd -D -e -p 2222 \
315:             -o PasswordAuthentication=no -o PermitRootLogin=no \
316:             -o PubkeyAuthentication=yes > "$SSH_DIR/sshd.log" 2>&1 &
317:           echo $! > "$SSH_DIR/sshd.pid"
318:           is_listening() {
319:             if [[ "$RUNNER_OS" == 'macOS' ]]; then
320:               if command -v nc >/dev/null 2>&1 && nc -z -w 1 127.0.0.1 2222 >/dev/null 2>&1; then
321:                 return 0
322:               fi
323:               command -v lsof >/dev/null 2>&1 && sudo lsof -nP -a -iTCP:2222 -sTCP:LISTEN >/dev/null 2>&1
324:             elif command -v ss >/dev/null 2>&1; then
325:               ss -ltn | grep -q ':2222 '
326:             elif command -v lsof >/dev/null 2>&1; then
327:               lsof -nP -a -iTCP:2222 -sTCP:LISTEN >/dev/null 2>&1
328:             else
329:               nc -z 127.0.0.1 2222 >/dev/null 2>&1
330:             fi
331:           }
332:           for _ in {1..120}; do
333:             if is_listening; then
334:               break
335:             fi
336:             if ! kill -0 "$(cat "$SSH_DIR/sshd.pid")" 2>/dev/null; then
337:               echo 'Local sshd exited before listening on port 2222.' >&2
338:               sed -n '1,160p' "$SSH_DIR/sshd.log" >&2
339:               exit 1
340:             fi
341:             sleep 1
342:           done
343:           if ! is_listening; then
344:             echo 'Local sshd did not start listening on port 2222.' >&2
345:             sed -n '1,160p' "$SSH_DIR/sshd.log" >&2
346:             exit 1
347:           fi
348:           nohup env PYTHONPATH="$AGENTSWEB_DIR" \
349:             python3 -m lolgames_tunnel client 127.0.0.1:2222 \
350:             --server agentsweb.space --name "$SSH_NAME" --public-port "$REQUESTED_SSH_PORT" \
351:             > "$SSH_DIR/tunnel.log" 2>&1 &
352:           echo $! > "$SSH_DIR/tunnel.pid"
353:           for _ in {1..45}; do
354:             grep -q '^ssh://' "$SSH_DIR/tunnel.log" && break
355:             if ! kill -0 "$(cat "$SSH_DIR/tunnel.pid")" 2>/dev/null; then
356:               break
357:             fi
358:             sleep 1
359:           done
360:           if ! grep -q '^ssh://' "$SSH_DIR/tunnel.log"; then
361:             echo 'AgentsWeb tunnel did not register.' >&2
362:             sed -n '1,160p' "$SSH_DIR/tunnel.log" >&2
363:             exit 1
364:           fi
365:           SSH_TUNNEL_URL="$(sed -n 's#^\(ssh://[^[:space:]]*\).*#\1#p' "$SSH_DIR/tunnel.log" | head -n 1)"
366:           endpoint="$(sed -nE 's#^ssh://([^:[:space:]]+):([0-9]+).*$#\1 \2#p' "$SSH_DIR/tunnel.log" | head -n 1)"
367:           if [[ -z "$endpoint" ]]; then
368:             echo 'AgentsWeb tunnel registration did not contain a usable SSH endpoint.' >&2
369:             sed -n '1,160p' "$SSH_DIR/tunnel.log" >&2
370:             exit 1
371:           fi
372:           read -r SSH_HOST SSH_PORT <<<"$endpoint"
373:           [[ -n "$SSH_HOST" && "$SSH_PORT" =~ ^[0-9]+$ ]]
374:           SSH_COMMAND="ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -i ~/.ssh/aiplay-agentsweb -p ${SSH_PORT} runner@${SSH_HOST}"
375:           {
376:             printf 'AGENTSWEB_HOST=%s\n' "$SSH_HOST"
377:             printf 'AGENTSWEB_PORT=%s\n' "$SSH_PORT"
378:             printf 'AGENTSWEB_COMMAND=%s\n' "$SSH_COMMAND"
379:             printf 'AGENTSWEB_TUNNEL_URL=%s\n' "$SSH_TUNNEL_URL"
380:           } >> "$GITHUB_ENV"
381:           {
382:             printf 'AGENTSWEB_HOST=%s\n' "$SSH_HOST"
383:             printf 'AGENTSWEB_PORT=%s\n' "$SSH_PORT"
384:             printf 'AGENTSWEB_COMMAND=%s\n' "$SSH_COMMAND"
385:             printf 'AGENTSWEB_TUNNEL_URL=%s\n' "$SSH_TUNNEL_URL"
386:           } > "$SSH_DIR/access.env"
387:           printf 'host=%s\nport=%s\ncommand=%s\n' "$SSH_HOST" "$SSH_PORT" "$SSH_COMMAND" >> "$GITHUB_OUTPUT"
388:           ssh_verified=''
389:           for _ in {1..3}; do
390:             if ssh -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null \
391:               -o BatchMode=yes -o ConnectTimeout=10 -o ConnectionAttempts=1 \
392:               -i "$SSH_KEY" -p "$SSH_PORT" "runner@$SSH_HOST" true; then
393:               ssh_verified='true'
394:               break
395:             fi
396:             sleep 5
397:           done
398:           if [[ "$ssh_verified" != 'true' ]]; then
399:             echo 'AgentsWeb registered, but the SSH endpoint is not reachable.' >&2
400:             sed -n '1,160p' "$SSH_DIR/tunnel.log" >&2
401:             exit 1
402:           fi
403:           if [[ "$SSH_ONLY_REQUEST" == 'true' ]]; then
404:             body=$'🔐 **SSH-only debugging session is ready.**\n\n'
405:           else
406:             body=$'🔐 **Temporary AgentsWeb SSH session is ready.**\n\n'
407:           fi
408:           body+="Run: https://github.com/${GITHUB_REPOSITORY}/actions/runs/${GITHUB_RUN_ID}"$'\n'
409:           body+="SSH URL: \`${SSH_TUNNEL_URL}\`"$'\n'
410:           body+="Host: \`${SSH_HOST}:${SSH_PORT}\`"$'\n\n'
411:           body+=$'Connect while the job is active:\n\n```sh\n'
412:           body+="${SSH_COMMAND}"$'\n```\n\n'
413:           if [[ "$SSH_ONLY_REQUEST" == 'true' ]]; then
414:             body+=$'This run skips OpenCode and holds the runner for five hours for interactive debugging.'
415:           fi
416:           comment_response="$(jq -n --arg body "$body" '{body: $body}' \
417:             | gh api "repos/${TARGET_REPOSITORY}/issues/${TRIGGER_ISSUE_NUMBER}/comments" \
418:               --method POST --input -)"
419:           comment_id="$(jq -r '.id // empty' <<<"$comment_response")"
420:           [[ -n "$comment_id" ]]
421:           printf 'comment_id=%s\n' "$comment_id" >> "$GITHUB_OUTPUT"
422: 
423:           /usr/bin/time -p printf '## Worker SSH\n\n```sh\n%s\n```\n' "$SSH_COMMAND" >> "$GITHUB_STEP_SUMMARY"
424:       - name: Prepare selected remix snapshot
425:         timeout-minutes: 15
426:         shell: bash
427:         run: /usr/bin/time -p node "$RUNTIME_DIR/scripts/remix-snapshot.mjs"
428:       - name: Load saved game checkpoint
429:         if: env.TEST_REQUEST != 'true' && env.SSH_ONLY_REQUEST != 'true'
