import assert from 'node:assert/strict'
import { MONSTER_LIST } from './src/data/monsters.js'
import { SKILLS, getSkill } from './src/data/skills.js'
import { Battle } from './src/game/battle.js'
import { createMonster, gainXp, knownMovePool, syncLearned, xpNeed } from './src/game/monsters.js'

for (const species of MONSTER_LIST) {
  const ids = species.learnset.map(([, id]) => id)
  assert(species.learnset.every(entry => Array.isArray(entry) && entry.length === 2 && Number.isInteger(entry[0]) && typeof entry[1] === 'string'), `${species.id}: malformed learnset`)
  assert(ids.every(id => SKILLS[id]), `${species.id}: unknown skill`)
  assert.equal(new Set(ids).size, ids.length, `${species.id}: duplicate skill`)
}

const created = createMonster('sprigling', 27)
assert(knownMovePool(created).some(move => move.id === 'pollen_dance'))
const legacyStored = { speciesId: 'sprigling', level: 1, moves: ['moonbeam'] }
assert.deepEqual(knownMovePool(legacyStored).map(move => move.id), ['moonbeam'])
const legacyLearned = { speciesId: 'sprigling', level: 1, learned: ['moonbeam'] }
assert.deepEqual(knownMovePool(legacyLearned).map(move => move.id), ['moonbeam'])
assert.deepEqual(knownMovePool({ speciesId: 'sprigling' }).map(move => move.id), ['tackle'])

const leveling = createMonster('sprigling', 26)
const gained = gainXp(leveling, xpNeed(26))
assert.equal(leveling.level, 27)
assert(gained.newSkills.some(skill => skill.id === 'pollen_dance'))
assert(knownMovePool(leveling).some(move => move.id === 'pollen_dance'))
const evolvedLegacy = { speciesId: 'dracoil', level: 24, moves: ['moonbeam'] }
syncLearned(evolvedLegacy)
assert.deepEqual(knownMovePool(evolvedLegacy).map(move => move.id), ['moonbeam', 'dragon_breath', 'bite', 'tail_swipe', 'wyrm_wave', 'dragon_dance'])

const player = createMonster('sprigling', 10, { moves: ['solar_flare'] })
const enemy = createMonster('cindercub', 10, { moves: ['solar_flare'] })
const battle = new Battle({ state: { party: [player], player: { name: 'Tester' }, time: { minutes: 0 } }, enemies: [enemy] })
player.hp = enemy.hp = 1000
battle.activeEnergy = 0
battle.useMove('player', knownMovePool(player).findIndex(move => move.id === 'solar_flare'))
assert.equal(battle.events.find(event => event.type === 'move')?.moveId, 'tackle')
battle.enemyEnergy = 0
const enemyChoice = battle.chooseEnemyMove()
assert.equal(enemyChoice.index, -1)
assert.equal(enemyChoice.skill.id, 'tackle')
battle.useMove('enemy', enemyChoice.index)
assert.equal(battle.events.filter(event => event.type === 'move').at(-1)?.moveId, 'tackle')

console.log(`Focused checks passed: ${MONSTER_LIST.length} learnsets; pool compatibility; level-up/evolution sync; player and enemy Tackle fallback.`)
